    }
    .dice-copy b { display: block; color: var(--purple-dark); font: 900 11px var(--pixel); }
    .dice-copy span { color: var(--ink-soft); font-size: 10px; line-height: 1.45; }
    .roll-button, .confirm-candidate {
      min-height: 42px;
      border: 2px solid var(--purple-dark);
      background: var(--yellow);
      box-shadow: inset 2px 2px #fff, inset -2px -2px #d9b96e, 2px 2px var(--shadow);
      font: 900 10px var(--pixel);
      cursor: pointer;
    }
    .roll-button:hover, .confirm-candidate:hover { background: var(--pink-pale); }
    .generator-result { min-height: 66px; padding: 9px; border: 1px solid var(--pink); background: rgba(255,255,255,.8); font: 10px/1.55 var(--pixel); }
    .generator-result b { display: block; margin-bottom: 3px; color: #b44578; }
    .generator-result span { display: block; color: var(--ink-soft); }
    .generator-actions { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; }
    .generator-actions button { min-height: 38px; border: 2px solid var(--purple-dark); background: var(--cream); box-shadow: inset 2px 2px #fff, inset -2px -2px #c9c4e1; font: 800 9px/1.35 var(--pixel); cursor: pointer; }
    .generator-actions button:last-child { background: var(--pink-pale); }
    .generator-actions button:disabled { opacity: .48; cursor: not-allowed; }
    .generator-footnote { margin: 0; color: var(--ink-soft); font: 9px/1.5 var(--pixel); }
    .style-settings { display: grid; gap: 10px; }
    .style-setting-label { display: block; margin-bottom: 5px; color: var(--purple-dark); font: 900 9px var(--pixel); }
    .wallpaper-options { display: grid; grid-template-columns: repeat(3,1fr); gap: 5px; }
    .wallpaper-choice { min-width: 0; display: grid; gap: 3px; padding: 4px; border: 1px solid var(--line); background: white; color: var(--ink-soft); font: 700 8px/1.2 var(--pixel); cursor: pointer; }
    .wallpaper-choice[aria-pressed="true"] { outline: 2px solid var(--pink); outline-offset: 1px; color: var(--ink); }
    .wallpaper-choice:disabled { opacity: .55; cursor: not-allowed; }
    .wallpaper-swatch { height: 18px; border: 1px solid rgba(69,66,154,.55); background: var(--swatch); }
    .wallpaper-choice--custom .wallpaper-swatch { display: grid; place-items: center; background: var(--swatch,linear-gradient(135deg,#fff0f6,#dcd9ff)); background-position: center; background-size: cover; color: var(--purple-dark); font: 900 13px/1 var(--pixel); }
    .wallpaper-import-button { width: 100%; min-height: 29px; margin-top: 5px; border: 1px dashed var(--purple); background: #fffaf5; color: var(--purple-dark); cursor: pointer; font: 800 9px var(--pixel); }
    .wallpaper-import-button:hover { background: var(--pink-pale); }
    .font-options { display: grid; grid-template-columns: repeat(2,1fr); gap: 5px; }
    .font-choice { min-height: 30px; padding: 5px; border: 1px solid var(--line); background: white; cursor: pointer; font-size: 10px; }
    .font-choice[aria-pressed="true"] { background: var(--pink-pale); outline: 1px solid var(--pink); }
    .story-font-controls { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; }
    .story-font-controls button { min-width: 36px; min-height: 36px; }
    .story-font-controls output { min-width: 42px; text-align: center; }
    .font-choice[data-font-choice="classic"] { font-family: "Songti SC",SimSun,serif; }
    .font-choice[data-font-choice="kai"] { font-family: "STKaiti","KaiTi",serif; }
    .font-choice[data-font-choice="round"] { font-family: "Microsoft YaHei",sans-serif; }
    .font-choice[data-font-choice="pixel"] { font-family: "MS Gothic",SimSun,monospace; }

    .projection-empty { width: 100%; display: grid; place-items: center; gap: 7px; min-height: 64px; padding: 14px; border: 1px dashed var(--line); background: rgba(255,255,255,.72); color: var(--ink-soft); text-align: center; font: 800 10px/1.55 var(--pixel); }
    .projection-empty--large { min-height: 220px; align-content: center; }
    .projection-empty b { color: var(--purple-dark); font-size: 14px; }
    .projection-empty span { max-width: 520px; font: 12px/1.7 var(--sans); }
    .profile-note { margin: 8px 0; font: 13px/1.7 var(--reading); }
    .location-visual--logo { display: grid; grid-template-rows: minmax(126px,1fr) auto; }
    .location-logo-mark { min-height: 126px; display: grid; place-items: center; background: linear-gradient(135deg,#fff0f6,#e8efff 55%,#fff4d9); color: var(--purple-dark); }
    .location-logo-mark svg { width: 76px !important; height: 76px !important; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; filter: drop-shadow(3px 3px 0 #fff); }

    /* 通用应用页 */
    .app-page {
      position: relative;
      height: 100%;
      min-height: 0;
      display: flex;
      flex-direction: column;
      overflow: hidden;
      padding: 18px;
      background:
        linear-gradient(90deg,rgba(255,255,255,.24) 1px,transparent 1px) 0 0/18px 18px,
        linear-gradient(rgba(255,255,255,.2) 1px,transparent 1px) 0 0/18px 18px,
        linear-gradient(135deg,#fff0f6,#eeedff 55%,#e3f5ff);
    }
    .page-banner {
      flex: 0 0 auto;
      display: grid;
      grid-template-columns: minmax(0,1fr) auto;
      align-items: center;
      gap: 18px;
      margin-bottom: 15px;
      padding: 16px 18px;
      border: 2px solid var(--purple-dark);
      background: var(--cream);
      box-shadow: 3px 3px var(--shadow);
    }
    .page-banner small { display: block; margin-bottom: 4px; color: #b45487; font: 900 10px var(--pixel); letter-spacing: .08em; }
    .page-banner h1 { margin: 0 0 5px; font: 900 clamp(22px,3vw,36px)/1 var(--reading); }
    .page-banner p { margin: 0; color: var(--ink-soft); font-size: 12px; line-height: 1.55; }
    .page-banner__stamp { color: var(--pink); font: 900 48px/1 var(--pixel); text-shadow: 3px 3px #d7d5ff; }
    .page-banner__decor { position: relative; width: 86px; height: 58px; color: #d85f9a; }
    .page-banner__decor svg { width: 100%; height: 100%; overflow: visible; fill: none; stroke: currentColor; stroke-width: 2.4; stroke-linecap: round; stroke-linejoin: round; filter: drop-shadow(3px 3px 0 #d7d5ff); }
    .page-banner__decor .decor-fill { fill: #ffe2ef; }
    .page-banner__decor .decor-star { fill: #ffe6a2; stroke: #b66b93; }

    /* 地点 */
    .places-layout { flex: 1; min-height: 0; display: grid; grid-template-columns: minmax(250px,.85fr) minmax(340px,1.35fr); gap: 14px; }
    .location-list, .detail-window { min-height: 0; display: grid; grid-template-rows: auto minmax(0,1fr); overflow: hidden; border: 2px solid var(--purple-dark); background: #fffaf5; box-shadow: 3px 3px var(--shadow); }
    .sub-titlebar { display: flex; justify-content: space-between; align-items: center; min-height: 31px; padding: 0 10px; border-bottom: 2px solid var(--purple-dark); background: var(--purple-pale); font: 800 11px var(--pixel); }
    .location-list__body { min-height: 0; display: grid; gap: 5px; padding: 8px; overflow: auto; }
    .location-button {
      --location-accent: var(--pink);
      width: 100%;
      min-height: 54px;
      display: grid;
      grid-template-columns: 40px minmax(0,1fr) auto;
      align-items: center;
      gap: 9px;
      padding: 7px 9px;
      border: 0;
      border-bottom: 0;
      background: transparent;
      text-align: left;
      cursor: pointer;
      transition: transform .16s ease, background .16s ease, box-shadow .16s ease;
    }
    .location-button:nth-child(2n) { --location-accent: var(--blue); }
    .location-button:nth-child(3n) { --location-accent: #e9b84e; }
    .location-button:hover { z-index: 1; background: #fff0f6; transform: translateX(4px); }
    .location-button.is-active { outline: 2px solid var(--location-accent); outline-offset: -2px; background: linear-gradient(90deg,color-mix(in srgb,var(--location-accent) 22%,#fff),#fff6dc); box-shadow: inset 5px 0 var(--location-accent); }
    .location-icon { width: 32px; height: 32px; display: grid; place-items: center; border: 2px solid var(--purple-dark); background: color-mix(in srgb,var(--location-accent) 18%,white); font: 900 14px var(--pixel); transition: transform .16s ease; }
    .location-icon svg { width: 21px; height: 21px; fill: none; stroke: var(--purple-dark); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
    .location-button:hover .location-icon, .location-button.is-active .location-icon { transform: rotate(-4deg) scale(1.06); }
    .location-name { font: 800 13px var(--sans); }
    .location-name small { display: block; margin-top: 2px; color: var(--ink-soft); font: 9px var(--pixel); }
    .location-density { padding: 3px 6px; border: 1px solid var(--purple); background: #fff; font: 9px var(--pixel); }
    .location-add-button { width: 100%; min-height: 58px; display: grid; grid-template-columns: 42px minmax(0,1fr); align-items: center; gap: 9px; padding: 8px 10px; border: 2px dashed var(--purple); background: #fff; color: var(--purple-dark); text-align: left; cursor: pointer; }
    .location-add-button:hover { background: var(--pink-pale); }
    .location-add-button__plus { width: 34px; height: 34px; display: grid; place-items: center; border: 2px solid var(--purple-dark); background: var(--yellow); font: 900 20px/1 var(--pixel); }
    .location-add-button b { display: block; font: 900 11px var(--pixel); }
    .location-add-button small { display: block; margin-top: 3px; color: var(--ink-soft); font: 9px var(--sans); }
    .detail-body { min-height: 0; overflow: auto; padding: 22px; background: linear-gradient(145deg,rgba(255,236,244,.72),rgba(255,255,255,.85) 45%,rgba(255,243,216,.65)); }
    .location-hero { display: grid; grid-template-columns: minmax(0,1fr) minmax(190px,250px); gap: 18px; align-items: center; margin-bottom: 16px; }
    .location-visual { margin: 0; overflow: hidden; border: 2px solid var(--purple-dark); background: white; box-shadow: 3px 3px var(--shadow); }
    .location-visual svg { display: block; width: 100%; height: 142px; }
    .location-visual figcaption { padding: 7px 9px; background: var(--cream); color: var(--ink-soft); font: 800 9px/1.35 var(--pixel); }
    .detail-kicker { color: #b24d83; font: 900 10px var(--pixel); }
    .detail-body h2 { margin: 8px 0 5px; font: 900 clamp(28px,4vw,48px)/1 var(--reading); }
    .detail-body > p, .location-copy { margin: 15px 0 20px; font: 14px/1.85 var(--reading); }
    .danger-grid { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 12px; margin-bottom: 20px; }
    .danger-item {
      position: relative;
      min-height: 72px;
      overflow: hidden;
      padding: 13px 15px 12px 46px;
      border: 0;
      border-radius: 17px 6px 17px 6px;
      background: linear-gradient(135deg,#ffe7f0,#fff8dc);
      box-shadow: 0 7px 18px rgba(69,66,154,.12), inset 0 1px rgba(255,255,255,.85);
    }
    .danger-item:nth-child(2) { background: linear-gradient(135deg,#e3f3ff,#ece9ff); }
    .danger-item:nth-child(3) { background: linear-gradient(135deg,#fff0c5,#ffe0eb); }
    .danger-item:nth-child(4) { background: linear-gradient(135deg,#e1f2e4,#e7efff); }
    .danger-item::before { content: "✦"; position: absolute; left: 14px; top: 13px; width: 23px; height: 23px; display: grid; place-items: center; border-radius: 50%; background: rgba(255,255,255,.78); color: #cf5f96; font: 900 12px/1 var(--pixel); box-shadow: 0 3px 8px rgba(74,64,121,.12); }
    .danger-item:nth-child(2)::before { content: "⌂"; color: #5d88bd; }
    .danger-item:nth-child(3)::before { content: "♡"; color: #ce688a; }
    .danger-item:nth-child(4)::before { content: "→"; color: #559779; }
    .danger-item small { display: block; color: #bd4f83; font: 800 9px var(--pixel); }
    .danger-item:nth-child(2) small { color: #527eac; }
    .danger-item:nth-child(4) small { color: #4d8a70; }
    .danger-item b { display: block; margin-top: 6px; font-size: 12px; line-height: 1.45; }
    .location-enter { width: 100%; min-height: 72px; display: grid; grid-template-columns: 52px minmax(0,1fr); align-items: center; gap: 11px; padding: 9px 12px; border: 2px solid var(--purple-dark); background: linear-gradient(90deg,var(--yellow),var(--pink-pale)); box-shadow: 2px 2px var(--shadow); text-align: left; cursor: pointer; transition: transform .16s ease, box-shadow .16s ease; }
    .location-enter__mark { width: 46px; height: 46px; display: grid; place-items: center; border: 2px solid var(--purple-dark); border-radius: 50% 50% 50% 10px; background: #fff; transform: rotate(-8deg); }
    .location-enter__mark svg { width: 28px; height: 28px; fill: none; stroke: var(--purple-dark); stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; transform: rotate(8deg); }
    .location-enter__copy { display: grid; gap: 3px; }
    .location-enter b { font: 900 11px/1.3 var(--pixel); }
    .location-enter small { color: var(--ink-soft); font: 9px/1.45 var(--sans); }
    .location-enter:hover { transform: translateY(-2px); box-shadow: 3px 4px var(--shadow); }
    .location-create { display: grid; gap: 14px; }
    .location-create__intro { margin: 0; color: var(--ink-soft); font: 13px/1.7 var(--reading); }
    .location-create__grid { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 10px; }
    .location-create label { display: grid; gap: 5px; color: var(--purple-dark); font: 800 9px var(--pixel); }
    .location-create label:last-child { grid-column: 1 / -1; }
    .location-create input, .location-create select, .location-create textarea { width: 100%; min-width: 0; padding: 9px 10px; border: 2px solid var(--line); background: #fff; color: var(--ink); font: 12px/1.5 var(--sans); }
    .location-create textarea { min-height: 88px; resize: vertical; }
    .location-create__save { min-height: 48px; border: 2px solid var(--purple-dark); background: linear-gradient(90deg,var(--yellow),var(--pink-pale)); box-shadow: 2px 2px var(--shadow); cursor: pointer; font: 900 11px var(--pixel); }

    /* 人物档案 */
    .files-layout { flex: 1; min-height: 0; display: grid; grid-template-columns: minmax(0,1fr); grid-template-rows: auto minmax(0,1fr); gap: 14px; }
    .file-list { min-height: 0; display: grid; grid-template-rows: auto auto; overflow: hidden; border: 2px solid var(--purple-dark); background: #fff; box-shadow: 3px 3px var(--shadow); }
    .file-list__body { display: flex; gap: 6px; padding: 6px; overflow-x: auto; }
    .file-entry { position: relative; width: 230px; flex: 0 0 230px; min-height: 66px; display: grid; grid-template-columns: 43px minmax(0,1fr); gap: 10px; align-items: center; padding: 9px 10px; border: 0; background: transparent; text-align: left; cursor: pointer; transition: background .16s ease, transform .16s ease; }
    .file-entry::after { content: ""; position: absolute; left: 10px; right: 10px; bottom: 0; height: 4px; background: var(--pink); transform: scaleX(0); transform-origin: left; transition: transform .18s ease; }
    .file-entry:hover { background: #fff4f8; transform: translateY(-2px); }
    .file-entry.is-active { background: var(--pink-pale); }
    .file-entry.is-active::after { transform: scaleX(1); }
    .file-face { width: 40px; height: 40px; display: grid; place-items: center; overflow: hidden; border: 2px solid var(--purple-dark); background: #e9e7ff; font: 900 11px var(--pixel); }
    .file-face img { width: 100%; height: 100%; display: block; object-fit: cover; object-position: center top; }
    .file-entry b { display: block; font-size: 13px; }
    .file-entry small { color: var(--ink-soft); font: 9px var(--pixel); }
    .profile { min-height: 0; display: grid; grid-template-rows: auto minmax(0,1fr); overflow: hidden; border: 2px solid var(--purple-dark); background: var(--cream); box-shadow: 3px 3px var(--shadow); }
    .profile-body { min-height: 0; overflow: auto; padding: 20px; }
    .profile-info { min-width: 0; }
    .profile-identity { display: grid; grid-template-columns: minmax(150px, 30%) minmax(0, 1fr); gap: 18px; align-items: start; margin-bottom: 16px; }
    .profile-summary { min-width: 0; }
    .profile-portrait { min-height: 260px; margin: 0; padding: 0; display: grid; grid-template-rows: minmax(0, 1fr) auto; overflow: hidden; border: 2px solid var(--purple-dark); background: #e9e7ff; color: inherit; font: inherit; cursor: pointer; box-shadow: 3px 3px var(--shadow); transition: transform .16s ease, box-shadow .16s ease; }
    .profile-portrait:hover { transform: translateY(-2px); box-shadow: 4px 5px var(--shadow); }
    .profile-portrait:focus-visible { outline: 3px solid var(--pink); outline-offset: 2px; }
    .profile-portrait img { width: 100%; height: 100%; min-height: 260px; max-height: 420px; display: block; object-fit: cover; object-position: center top; }
    .profile-portrait figcaption, .profile-portrait__caption { padding: 6px 8px; border-top: 1px solid var(--line); background: #fff; color: var(--ink-soft); font: 800 8px var(--pixel); text-align: center; }
    .profile-state { display: inline-flex; margin: 8px 0 2px; padding: 5px 8px; border: 1px solid var(--pink); background: var(--pink-pale); color: #a83e72; font: 800 9px var(--pixel); }
    .profile h2 { margin: 0 0 4px; font: 900 30px var(--reading); }
    .profile-code { color: #ac4e7e; font: 800 10px var(--pixel); }
    .profile-grid { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 7px; margin-top: 16px; }
    .profile-field { padding: 9px; border: 1px solid var(--line); background: white; }
    .profile-field small { display: block; margin-bottom: 4px; color: var(--purple); font: 800 9px var(--pixel); }
    .profile-field span { font-size: 12px; line-height: 1.5; }

    /* CP 后续 */
    .cp-layout { flex: 1; min-height: 0; display: grid; grid-template-columns: minmax(250px,.8fr) minmax(380px,1.3fr); gap: 14px; }
    .cp-list, .cp-detail { min-height: 0; display: grid; grid-template-rows: auto minmax(0,1fr); overflow: hidden; border: 2px solid var(--purple-dark); background: #fffaf5; box-shadow: 3px 3px var(--shadow); }
    .cp-list__body { min-height: 0; display: grid; gap: 6px; overflow: auto; padding: 6px; }
    .cp-card { position: relative; width: 100%; min-height: 82px; padding: 11px 34px 11px 13px; border: 0; background: transparent; text-align: left; cursor: pointer; transition: transform .16s ease, background .16s ease; }
    .cp-card::after { content: "›"; position: absolute; right: 12px; top: 50%; transform: translateY(-50%); color: var(--pink); font: 900 24px/1 var(--pixel); opacity: .55; transition: transform .16s ease, opacity .16s ease; }
    .cp-card:hover { transform: translateX(3px); }
    .cp-card:hover, .cp-card.is-active { background: linear-gradient(90deg,#fff0c9,#ffe3ee); }
    .cp-card.is-active::after { transform: translate(4px,-50%); opacity: 1; }
    .cp-names { display: flex; align-items: center; gap: 7px; font: 900 13px var(--sans); }
    .cp-heart { color: #dc5b99; font-size: 17px; }
    .cp-card p { margin: 6px 0 0; color: var(--ink-soft); font: 10px/1.4 var(--pixel); }
    .cp-detail__body { min-height: 0; overflow: auto; padding: 20px; }
    .relationship-head { display: flex; justify-content: space-between; gap: 14px; align-items: flex-start; padding-bottom: 8px; border-bottom: 0; }
    .relationship-head h2 { margin: 4px 0; font: 900 28px var(--reading); }
    .relationship-tag { padding: 6px 9px; border: 2px solid var(--purple-dark); background: var(--pink-pale); font: 800 10px var(--pixel); white-space: nowrap; }
    .relationship-summary { margin: 16px 0; font: 14px/1.8 var(--reading); }
    .relationship-history { position: relative; margin: 15px 0 13px; padding: 15px 17px 15px 52px; border-radius: 18px 7px 18px 7px; background: linear-gradient(135deg,#eeeaff,#fff0f5 58%,#fff7d8); box-shadow: 0 7px 18px rgba(69,66,154,.12); }
    .relationship-history::before { content: "↝"; position: absolute; left: 16px; top: 16px; width: 25px; height: 25px; display: grid; place-items: center; border-radius: 50%; background: white; color: #b74d83; font: 900 15px/1 var(--pixel); }
    .relationship-history small, .relationship-current small { display: block; margin-bottom: 6px; color: #a84779; font: 900 9px var(--pixel); letter-spacing: .04em; }
    .relationship-history p, .relationship-current p { margin: 0; font: 13px/1.75 var(--reading); }
    .relationship-current { margin: 0 0 16px; }
    .relationship-overview { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 7px; margin: 12px 0 16px; }
    .relationship-fact { padding: 9px 10px; border: 1px solid var(--line); background: white; }
    .relationship-fact small { display: block; margin-bottom: 4px; color: #ad4779; font: 900 8px var(--pixel); }
    .relationship-fact b { font-size: 11px; line-height: 1.45; }
    .relationship-meter { margin: 12px 0 18px; }
    .relationship-meter__label { display: flex; justify-content: space-between; margin-bottom: 5px; color: var(--ink-soft); font: 800 9px var(--pixel); }
    .relationship-meter__track { height: 10px; overflow: hidden; border: 1px solid var(--purple-dark); background: #e5e2f7; }
    .relationship-meter__fill { height: 100%; background: linear-gradient(90deg,var(--blue),var(--pink),#e9b84e); }
    .relationship-paths { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 12px; }
    .relationship-path { padding: 5px 8px; border: 1px solid var(--line); background: var(--cream); color: var(--ink-soft); font: 800 9px var(--pixel); }
    .timeline { position: relative; margin-left: 8px; padding-left: 22px; border-left: 3px solid var(--purple-pale); }
    .timeline-item { position: relative; margin-bottom: 14px; padding: 10px 12px; border: 1px solid var(--line); background: white; }
    .timeline-item::before { content: ""; position: absolute; left: -31px; top: 13px; width: 10px; height: 10px; border: 2px solid var(--purple-dark); background: var(--pink); }
    .timeline-item small { color: var(--purple); font: 800 9px var(--pixel); }
    .timeline-item b { display: block; margin-top: 4px; font-size: 12px; }
    .relationship-question { margin-top: 15px; padding: 14px; border: 1px solid var(--red); background: linear-gradient(135deg,#fff0f5,#fff6d8); box-shadow: inset 0 0 0 4px rgba(255,255,255,.6); }
    .relationship-question small { display: block; color: #bc486a; font: 900 9px var(--pixel); }
    .relationship-question p { margin: 6px 0 0; font: 13px/1.65 var(--reading); }

    /* 小剧场 */
    .theater-layout { flex: 1; min-height: 0; display: grid; grid-template-columns: 240px minmax(0,1fr); gap: 14px; }
    .theater-menu { min-height: 0; display: grid; grid-template-rows: auto minmax(0,1fr); overflow: hidden; border: 2px solid var(--purple-dark); background: #fffaf5; box-shadow: 3px 3px var(--shadow); }
    .theater-stage { border: 2px solid var(--purple-dark); background: #fffaf5; box-shadow: 3px 3px var(--shadow); }
    .theater-menu__body { min-height: 0; display: grid; gap: 5px; overflow: auto; padding: 6px; }
    .theater-item { --scene-accent: var(--pink); position: relative; width: 100%; min-height: 70px; display: grid; grid-template-columns: 32px minmax(0,1fr); gap: 8px; align-items: center; padding: 9px 10px; border: 0; background: transparent; text-align: left; cursor: pointer; transition: transform .16s ease, background .16s ease; }
    .theater-item:nth-child(2) { --scene-accent: var(--blue); }
    .theater-item:nth-child(3) { --scene-accent: #e9b84e; }
    .theater-item::before { content: attr(data-scene-index); width: 29px; height: 29px; display: grid; place-items: center; border: 2px solid var(--purple-dark); border-radius: 50%; background: color-mix(in srgb,var(--scene-accent) 28%,white); font: 900 9px var(--pixel); }
    .theater-item:hover { transform: translateX(3px); }
    .theater-item:hover, .theater-item.is-active { background: linear-gradient(90deg,color-mix(in srgb,var(--scene-accent) 23%,white),#fff8e6); }
    .theater-item.is-active { box-shadow: inset 4px 0 var(--scene-accent); }
    .theater-item-copy { min-width: 0; }
    .theater-item b { display: block; font-size: 12px; }
    .theater-item small { color: var(--ink-soft); font: 9px var(--pixel); }
    .theater-stage { --pointer-x: 50%; --pointer-y: 40%; --tilt-x: 0deg; --tilt-y: 0deg; position: relative; min-width: 0; min-height: 0; display: grid; grid-template-rows: auto auto auto minmax(0,1fr); overflow: hidden; isolation: isolate; }
    .theater-stage::before { content: ""; position: absolute; inset: 0; z-index: 0; pointer-events: none; background: radial-gradient(circle at 14% 18%,rgba(242,154,194,.2) 0 2px,transparent 3px) 0 0/24px 24px; opacity: .5; animation: theaterDust 18s linear infinite; }
    .theater-stage::after { content: ""; position: absolute; inset: 31px 0 0; z-index: 4; pointer-events: none; background: radial-gradient(circle 220px at var(--pointer-x) var(--pointer-y),rgba(255,233,173,.18),transparent 72%); mix-blend-mode: multiply; }
    .theater-toolbar { position: relative; z-index: 6; display: flex; align-items: center; gap: 6px; min-height: 39px; padding: 5px 8px; border-bottom: 1px solid var(--line); background: linear-gradient(90deg,#fff4f8,#fff9df); }
    .scene-counter { margin-right: auto; color: #a94474; font: 900 9px/1 var(--pixel); }
    .motion-toggle { min-height: 27px; padding: 4px 7px; border: 1px solid var(--purple-dark); background: rgba(255,255,255,.82); font: 800 8px/1.25 var(--pixel); cursor: pointer; }
    .motion-toggle[aria-pressed="true"] { background: var(--pink-pale); box-shadow: inset 2px 2px rgba(107,100,202,.18); }
    .motion-toggle:disabled { opacity: .45; cursor: not-allowed; }
    .scene-progress { position: relative; z-index: 6; height: 4px; background: #e2def7; }
    .scene-progress span { display: block; width: 0; height: 100%; background: linear-gradient(90deg,var(--pink),#e9b84e,var(--blue)); transition: width .1s linear; }
    .stage-viewport { position: relative; z-index: 2; height: auto; min-height: 0; overflow: auto; overscroll-behavior: contain; touch-action: pan-y; scroll-behavior: smooth; scrollbar-color: var(--pink) var(--purple-pale); }
    .stage-body { --drag-x: 0px; min-height: 100%; padding: 28px clamp(20px,4vw,52px) 70px; background: linear-gradient(90deg,rgba(242,154,194,.08) 1px,transparent 1px) 0 0/28px 28px,#fffdf8; transform: perspective(1000px) translateX(var(--drag-x)) rotateX(var(--tilt-x)) rotateY(var(--tilt-y)); transform-origin: 50% 40%; transition: transform .34s cubic-bezier(.22,.8,.28,1), opacity .22s ease; will-change: transform; }
    .theater-stage[data-motion-state="dragging"] .stage-body { transition: none; cursor: grabbing; }
    .theater-stage[data-motion-state="entering"] .stage-body { animation: sceneEnter .42s cubic-bezier(.22,.8,.28,1); }
    .stage-label { color: #ba4e82; font: 900 10px var(--pixel); }
    .stage-body h2 { margin: 9px 0 5px; font: 900 31px var(--reading); }
    .stage-sub { color: var(--ink-soft); font: 10px var(--pixel); }
    .stage-copy { max-width: 720px; margin: 24px auto 0; font: 15px/2 var(--reading); }
    .stage-copy p { margin: 0 0 1.2em; }
    .stage-reveal { opacity: .18; transform: translateY(16px); filter: blur(1px); transition: opacity .45s ease, transform .45s ease, filter .45s ease; }
    .stage-reveal.is-visible { opacity: 1; transform: none; filter: none; }
    .stage-dialogue { padding: 11px 15px; border-left: 4px solid var(--pink); background: var(--pink-pale); }
    .gesture-hint { position: absolute; z-index: 7; left: 50%; bottom: 9px; transform: translateX(-50%); width: max-content; max-width: calc(100% - 20px); padding: 5px 9px; border: 1px solid rgba(69,66,154,.5); background: rgba(255,250,242,.9); color: var(--ink-soft); font: 800 8px/1.3 var(--pixel); pointer-events: none; }
    @keyframes sceneEnter { from { opacity: 0; transform: perspective(1000px) translateX(34px) rotateY(-2deg); } to { opacity: 1; transform: perspective(1000px) translateX(0) rotateY(var(--tilt-y)); } }
    @keyframes theaterDust { to { background-position: 120px 70px; } }

    .dock {
      min-width: 0;
      display: flex;
      justify-content: flex-end;
      align-items: center;
      gap: 3px;
      margin-left: auto;
      padding: 0;
      border: 0;
      background: transparent;
    }
    .dock-button {
      min-width: 46px;
      min-height: 24px;
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 3px;
      padding: 2px 5px;
      border: 1px solid var(--purple-dark);
      background: #eeecff;
      box-shadow: inset 2px 2px #fff, inset -2px -2px #bcb7df;
      font: 800 8px var(--pixel);
      cursor: pointer;
    }
    .dock-button:hover, .dock-button.is-active { background: var(--pink-pale); box-shadow: inset -2px -2px #fff, inset 2px 2px #b76591; }
    .dock-button__dot { width: 14px; height: 14px; display: grid; place-items: center; border: 1px solid var(--purple-dark); background: white; }
    .dock-button__dot svg { width: 10px; height: 10px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }

    .toast {
      position: fixed;
      z-index: 80;
      right: 18px;
      bottom: 18px;
      width: min(340px,calc(100vw - 28px));
      padding: 11px 13px;
      border: 2px solid var(--purple-dark);
      background: var(--yellow);
      box-shadow: 4px 4px var(--shadow);
      font: 700 11px/1.55 var(--pixel);
      opacity: 0;
      transform: translateY(12px);
      pointer-events: none;
      transition: .2s ease;
    }
    .toast.is-visible { opacity: 1; transform: none; }

    @media (max-width: 920px) {
      :root { --dock: 46px; }
      .game-shell { grid-template-rows: var(--top) minmax(0,1fr); }
      .desktop { grid-template-columns: 1fr; padding: 10px; }
      .desktop-icons { display: none; }
      .main-grid { grid-template-columns: minmax(0,1fr) 238px; grid-template-rows: minmax(0,1fr); }
      .main-side { border-left: 2px solid var(--line); }
      .story-panel { border-right: 0; }
      .places-layout, .files-layout, .cp-layout, .theater-layout { grid-template-columns: 1fr; grid-template-rows: auto minmax(0,1fr); }
      .location-list__body, .file-list__body, .cp-list__body, .theater-menu__body { max-height: 210px; overflow: auto; }
      .dock { display: flex; justify-content: flex-end; }
      .toast { bottom: 12px; }
      .dock-button { min-width: 38px; flex: 0 0 auto; padding: 2px 4px; }
      .theater-toolbar { flex-wrap: wrap; }
      .stage-viewport { height: auto; }
      .location-hero { grid-template-columns: 1fr; }
    }

    @media (max-width: 560px) {
      :root { --top: 32px; --dock: 40px; }
      .game-shell { min-height: 0; }
      .system-bar { padding: 0 5px; gap: 5px; }
      .start-chip { min-width: auto; height: 24px; padding: 0 6px; font-size: 10px; }
      .system-title { display: none; }
      .system-status span:not(.status-dot) { display: none; }
      .desktop { padding: 4px; }
      .window { border-width: 2px; box-shadow: 3px 3px 0 rgba(57,54,112,.48); }
      .window-titlebar { gap: 3px; padding: 0 4px 0 6px; border-bottom-width: 2px; font-size: 9px; }
      .window-titlebar__name { max-width: 72px; }
      .window-controls { gap: 2px; }
      .window-control { width: 18px; height: 18px; border-width: 1px; font-size: 10px; }
      .window-control[data-show-native-chat] { display: grid; }
      .window-control[data-close-ui] { display: none; }
      .story-head { padding: 5px 8px; gap: 6px; }
      .story-head h1 { margin-bottom: 1px; font-size: 13px; }
      .story-head p { overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
      .episode-number { min-width: 28px; font-size: 20px; }
      .story-scroll { min-height: 64px; padding: 12px 12px 18px; }
      .story-copy { font-size: var(--story-font-size,13px); line-height: 1.75; }
      .input-zone { padding: 5px 6px 6px; }
      .deflag-row { grid-template-columns: repeat(2,minmax(0,1fr)); gap: 4px; padding-bottom: 4px; }
      .pixel-button.option-card:nth-child(n) { transform: none; }
      .pixel-button.option-card {
        min-height: 42px;
        grid-template-columns: 18px minmax(0,1fr) auto;
        grid-template-areas: "number title risk";
        column-gap: 4px;
        padding: 4px 5px 4px 4px;
      }
      .option-number { width: 18px; height: 18px; border-width: 1px; font-size: 8px; }
      .option-title { overflow: hidden; font-size: 9px; line-height: 1.2; }
      .option-desc { display: none; }
      .option-risk { align-self: center; padding: 1px 3px; font-size: 6px; }
      .app-page { padding: 10px; }
      .page-banner { padding: 12px; }
      .page-banner__stamp { display: none; }
      .page-banner__decor { display: none; }
      .detail-body, .cp-detail__body, .stage-body { padding: 15px; }
      .stage-body { padding-bottom: 62px; }
      .profile-body { padding: 15px; }
      .danger-grid, .profile-grid { grid-template-columns: 1fr; }
      .location-create__grid { grid-template-columns: 1fr; }
      .location-create label:last-child { grid-column: auto; }
      .relationship-overview { grid-template-columns: 1fr; }
      .dock { gap: 1px; padding: 0; }
      .dock-button { width: 22px; min-width: 22px; min-height: 20px; font-size: 0; flex-direction: row; gap: 0; padding: 1px; }
      .dock-button__dot { width: 12px; height: 12px; }
      .dock-button__dot svg { width: 8px; height: 8px; }
      .toast { right: 8px; bottom: 9px; }
      .main-grid { grid-template-columns: 1fr; grid-template-rows: minmax(0,1fr) auto; }
      .main-side { display: grid; grid-template-columns: repeat(3,minmax(0,1fr)); grid-template-rows: repeat(2,minmax(0,1fr)); gap: 3px; max-height: 62px; border-left: 0; border-top: 2px solid var(--line); padding: 3px; }
      .main-side .mini-window { margin: 0; }
      .main-side .mini-window__body { display: none; }
      .main-side .mini-window__title { height: 25px; overflow: hidden; padding: 4px 17px 4px 5px; border-bottom: 0; white-space: nowrap; text-overflow: ellipsis; }
    }

    @media (prefers-reduced-motion: reduce) {
      *,*::before,*::after { transition-duration: .01ms !important; animation-duration: .01ms !important; }
      .stage-body { transform: none !important; }
      .stage-reveal { opacity: 1; transform: none; filter: none; }
      .theater-stage::after { display: none; }
      .wallpaper-scene img, .ambient-layer::before, .ambient-layer::after { animation: none !important; }
      .wallpaper-scene img { transform: scale(1.035) !important; }
    }
  </style>
</head>
<body>
  <div class="game-shell" data-current-view="main" data-wallpaper="blush" data-font="classic">
    <div class="wallpaper-stage" aria-hidden="true">
      <div class="wallpaper-scene" data-scene="blush"><img src="https://raw.githubusercontent.com/jiuyi777/manga-world-simulator/main/gl/assets/backgrounds/subway-morning.png" alt=""></div>
      <div class="wallpaper-scene" data-scene="sky"><img src="https://raw.githubusercontent.com/jiuyi777/manga-world-simulator/main/gl/assets/backgrounds/campus-afternoon.png" alt=""></div>
      <div class="wallpaper-scene" data-scene="sunset"><img src="https://raw.githubusercontent.com/jiuyi777/manga-world-simulator/main/gl/assets/backgrounds/cafe-sunset.png" alt=""></div>
      <div class="wallpaper-scene" data-scene="night"><img src="https://raw.githubusercontent.com/jiuyi777/manga-world-simulator/main/gl/assets/backgrounds/convenience-rain.png" alt=""></div>
      <div class="wallpaper-scene" data-scene="mint"><img src="https://raw.githubusercontent.com/jiuyi777/manga-world-simulator/main/gl/assets/backgrounds/apartment-evening.png" alt=""></div>
      <div class="wallpaper-scene" data-scene="custom"><img data-custom-wallpaper alt="用户导入的自定义场景背景"></div>
      <div class="ambient-layer"></div>
    </div>
    <button class="reopen-window" type="button" data-reopen-ui aria-hidden="true" tabindex="-1"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="5" width="18" height="14" rx="2"/><path d="M3 9h18M7 7h.01M10 7h.01"/></svg>打开游戏界面</button>
    <header class="system-bar">
      <div class="start-chip">FLAG_OS</div>
      <div class="system-title">绝不想变成BL！— 世界修正力观测终端</div>
      <div class="system-status"><span class="status-dot" aria-hidden="true"></span><span>2025/04/15　08:15　晴转多云</span></div>
    </header>

    <div class="desktop">
      <nav class="desktop-icons" aria-label="桌面应用">
        <button class="app-icon is-active" type="button" data-nav="main" data-testid="desktop-main" aria-current="page"><span class="app-icon__pic" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M6.2 9.1 5 4.8l4 2.1a8.2 8.2 0 0 1 6 0l4-2.1-1.2 4.3A6.8 6.8 0 0 1 19 13c0 3.6-3.1 6-7 6s-7-2.4-7-6c0-1.5.4-2.8 1.2-3.9Z"/><path d="M9 12h.01M15 12h.01M10 15c1.2.8 2.8.8 4 0"/></svg></span><span class="app-icon__label">主界面</span></button>
        <button class="app-icon" type="button" data-nav="places" data-testid="desktop-places"><span class="app-icon__pic" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M20 10c0 5-8 10-8 10S4 15 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/></svg></span><span class="app-icon__label">地点</span></button>
        <button class="app-icon" type="button" data-nav="profiles" data-testid="desktop-profiles"><span class="app-icon__pic" aria-hidden="true"><svg viewBox="0 0 24 24"><rect x="3" y="5" width="18" height="14" rx="1.5"/><circle cx="9" cy="11" r="2.4"/><path d="M5.8 16c.7-1.8 2-2.7 3.2-2.7s2.5.9 3.2 2.7M14.5 10H19M14.5 14H19"/></svg></span><span class="app-icon__label">人物档案</span></button>
        <button class="app-icon" type="button" data-nav="future" data-testid="desktop-future"><span class="app-icon__pic" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M8.2 18.5C4.4 16 2.5 13.8 2.5 10.8A3.3 3.3 0 0 1 8.2 8.5 3.3 3.3 0 0 1 14 10.8c0 3-1.9 5.2-5.8 7.7Z"/><path d="M15.8 15.5c3.8-2.5 5.7-4.7 5.7-7.7a3.3 3.3 0 0 0-5.7-2.3A3.3 3.3 0 0 0 10 7.8"/></svg></span><span class="app-icon__label">CP后续</span></button>
        <button class="app-icon" type="button" data-nav="theater" data-testid="desktop-theater"><span class="app-icon__pic" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M4 4h16v16H4zM4 5c4 2 5 5 5 9s-2 6-5 6M20 5c-4 2-5 5-5 9s2 6 5 6M9 17h6"/></svg></span><span class="app-icon__label">小剧场</span></button>
      </nav>

      <section class="window" aria-label="游戏主窗口">
        <div class="window-titlebar">
          <span class="window-titlebar__spark">✿</span>
          <span class="window-titlebar__name" data-window-title>MAIN.exe ／ 主界面</span>
          <nav class="dock" aria-label="主导航">
            <button class="dock-button is-active" type="button" data-nav="main" data-testid="dock-main" aria-current="page"><span class="dock-button__dot" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M6.2 9.1 5 4.8l4 2.1a8.2 8.2 0 0 1 6 0l4-2.1-1.2 4.3A6.8 6.8 0 0 1 19 13c0 3.6-3.1 6-7 6s-7-2.4-7-6c0-1.5.4-2.8 1.2-3.9Z"/><path d="M9 12h.01M15 12h.01M10 15c1.2.8 2.8.8 4 0"/></svg></span>主界面</button>
            <button class="dock-button" type="button" data-nav="places" data-testid="dock-places"><span class="dock-button__dot" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M20 10c0 5-8 10-8 10S4 15 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/></svg></span>地点</button>
            <button class="dock-button" type="button" data-nav="profiles" data-testid="dock-profiles"><span class="dock-button__dot" aria-hidden="true"><svg viewBox="0 0 24 24"><rect x="3" y="5" width="18" height="14" rx="1.5"/><circle cx="9" cy="11" r="2.4"/><path d="M5.8 16c.7-1.8 2-2.7 3.2-2.7s2.5.9 3.2 2.7M14.5 10H19M14.5 14H19"/></svg></span>档案</button>
            <button class="dock-button" type="button" data-nav="future" data-testid="dock-future"><span class="dock-button__dot" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M8.2 18.5C4.4 16 2.5 13.8 2.5 10.8A3.3 3.3 0 0 1 8.2 8.5 3.3 3.3 0 0 1 14 10.8c0 3-1.9 5.2-5.8 7.7Z"/><path d="M15.8 15.5c3.8-2.5 5.7-4.7 5.7-7.7a3.3 3.3 0 0 0-5.7-2.3A3.3 3.3 0 0 0 10 7.8"/></svg></span>后续</button>
            <button class="dock-button" type="button" data-nav="theater" data-testid="dock-theater"><span class="dock-button__dot" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M4 4h16v16H4zM4 5c4 2 5 5 5 9s-2 6-5 6M20 5c-4 2-5 5-5 9s2 6 5 6M9 17h6"/></svg></span>剧场</button>
          </nav>
          <div class="window-controls"><span class="window-control" aria-hidden="true">—</span><button class="window-control" type="button" data-show-native-chat aria-label="显示原生聊天">↕</button><button class="window-control" type="button" data-close-ui aria-label="关闭界面，只看背景">×</button></div>
        </div>
        <div class="window-body">
          <section class="view is-active" data-view-panel="main" aria-labelledby="main-title">
            <div class="main-grid">
              <article class="story-panel">
                <header class="story-head">
                  <div class="episode-number">01</div>
                  <div><h1 id="main-title">通勤地铁里的标准开局</h1><p>MAIN STORY / 城市 · 通勤路上 / 08:15</p></div>
                </header>
                <div class="story-scroll">
                  <div class="story-copy">
                    <p>你睁开眼时，地铁刚好驶进隧道。玻璃上映出一张完全陌生、但毫无疑问属于你的脸。周围的人没有尖叫，也没有察觉这具身体里已经换了一个来自异世界的灵魂。</p>
                    <p>真正不正常的是站在车门边的两位女性。一个低头替另一个整理歪掉的领带，动作本来算不上出格，可他们身后突然绽开了大片粉色玫瑰，头顶甚至浮出一行闪烁的巨大拟声词——</p>
                    <div class="meta-line">【怦 然 心 动】<br>只有你能看见的漫画特效。根据经验，这通常意味着某种 GL Flag 正在成形。</div>
                    <p class="speech">“麻烦让一下。”身后有人开口。你刚侧过身，列车突然急刹，那人顺势撑住你身后的车门，把你困在了手臂与玻璃之间。</p>
                    <p>玫瑰背景瞬间从浅粉变成了刺眼的玫红。很好。世界修正力显然把目标从那两个人身上挪到了你这里。</p>
                  </div>
                </div>
                <div class="input-zone">
                  <div class="deflag-row" aria-label="拔旗方式">
                    <button class="pixel-button option-card" type="button" data-deflag="拉人破独处"><span class="option-number">01</span><span class="option-title">拉人破独处</span><span class="option-risk">稳妥</span><span class="option-desc">找第三个人加入，打断世界制造的双人空间。</span></button>
                    <button class="pixel-button option-card" type="button" data-deflag="装傻不接茬"><span class="option-number">02</span><span class="option-title">装傻不接茬</span><span class="option-risk">观察</span><span class="option-desc">把暧昧台词当普通对话，让 Flag 没有落点。</span></button>
