  <script>
    (() => {
      const syncHostViewport = () => {
        const frame = window.frameElement;
        if (frame?.dataset?.mangaWorldSameFloorFrame) {
          document.documentElement.style.setProperty('--manga-viewport-height', '100%');
          frame.style.setProperty('width', '100%', 'important');
          frame.style.setProperty('height', '100%', 'important');
          frame.style.setProperty('max-height', 'none', 'important');
          frame.style.setProperty('overflow', 'hidden', 'important');
          return;
        }
        const hostViewport = window.parent !== window ? window.parent.visualViewport : window.visualViewport;
        const hostHeight = hostViewport?.height || (window.parent !== window ? window.parent.innerHeight : window.innerHeight);
        const hostWidth = window.parent !== window ? window.parent.innerWidth : window.innerWidth;
        const isNarrowHost = hostWidth <= 560;
        let availableHeight = hostHeight || window.innerHeight || 720;
        let messageChrome = 0;
        if (frame?.ownerDocument) {
          const hostChat = frame.ownerDocument.querySelector('#chat');
          const hostMessage = frame.closest('.mes');
          const frameHeight = frame.getBoundingClientRect().height;
          const messageHeight = hostMessage?.getBoundingClientRect().height ?? frameHeight;
          messageChrome = Math.max(0, messageHeight - frameHeight);
          if (hostChat && !isNarrowHost) availableHeight = hostChat.clientHeight - messageChrome;
        }
        const viewportCeiling = Math.max(320, hostHeight - 8);
        const safeHeight = Math.max(320, Math.round(isNarrowHost ? viewportCeiling : Math.min(availableHeight, viewportCeiling)));
        document.documentElement.style.setProperty('--manga-viewport-height', `${safeHeight}px`);
        if (frame) {
          frame.style.setProperty('height', `${safeHeight}px`, 'important');
          frame.style.setProperty('max-height', `${safeHeight}px`, 'important');
          frame.style.setProperty('overflow', 'hidden', 'important');
          frame.setAttribute('scrolling', 'no');
        }
      };
      syncHostViewport();
      window.addEventListener('resize', syncHostViewport, { passive: true });

      const shell = document.querySelector('.game-shell');
      const navButtons = [...document.querySelectorAll('[data-nav]')];
      const panels = [...document.querySelectorAll('[data-view-panel]')];
      const windowTitle = document.querySelector('[data-window-title]');
      const toast = document.querySelector('.toast');
      const closeUIButton = document.querySelector('[data-close-ui]');
      const reopenUIButton = document.querySelector('[data-reopen-ui]');
      const titles = { main: 'MAIN.exe ／ 主界面', places: 'LOCATION.exe ／ 地点', profiles: 'PROFILE.exe ／ 人物档案', future: 'AFTER.exe ／ CP后续', theater: 'THEATER.exe ／ 小剧场' };
      let toastTimer;

      function notify(message) {
        toast.textContent = message;
        toast.classList.add('is-visible');
        clearTimeout(toastTimer);
        toastTimer = setTimeout(() => toast.classList.remove('is-visible'), 2400);
      }

      function switchView(view) {
        if (view !== 'theater') {
          stopAutoReading(true);
          disableTilt();
          stopTheaterAudio(true);
        }
        shell.dataset.currentView = view;
        windowTitle.textContent = titles[view];
        navButtons.forEach(button => {
          const active = button.dataset.nav === view;
          button.classList.toggle('is-active', active);
          if (active) button.setAttribute('aria-current', 'page'); else button.removeAttribute('aria-current');
        });
        panels.forEach(panel => {
          const active = panel.dataset.viewPanel === view;
          panel.hidden = !active;
          panel.classList.toggle('is-active', active);
          if (active) panel.scrollTop = 0;
        });
      }
      navButtons.forEach(button => button.addEventListener('click', () => switchView(button.dataset.nav)));

      function setUIHidden(hidden) {
        shell.dataset.uiHidden = String(hidden);
        reopenUIButton.setAttribute('aria-hidden',String(!hidden));
        reopenUIButton.tabIndex = hidden ? 0 : -1;
        if (!hidden) closeUIButton.focus({preventScroll:true});
      }
      closeUIButton.addEventListener('click', () => {
        stopAutoReading(true);
        disableTilt();
        stopTheaterAudio(true);
        setUIHidden(true);
        reopenUIButton.focus({preventScroll:true});
      });
      reopenUIButton.addEventListener('click', () => setUIHidden(false));

      const wallpaperChoices = [...document.querySelectorAll('[data-wallpaper-choice]')];
      const fontChoices = [...document.querySelectorAll('[data-font-choice]')];
      const storyFontKey = 'flag-ui-story-font-size';
      const storyCopy = document.querySelector('.story-copy');
      const storyFontButtons = [...document.querySelectorAll('[data-story-font]')];
      const storyFontValue = document.querySelector('[data-story-font-value]');
