const normalize = value => String(value ?? '').trim().toLowerCase();

function scoreGroup(profile, group) {
  const target = group.appearanceProfile ?? {};
  const weights = {visualAge: 8, hairColor: 6, eyeColor: 5, hairStyle: 3};
  let score = 0;
  let compared = 0;
  for (const [field, weight] of Object.entries(weights)) {
    const wanted = normalize(profile?.[field]);
    if (!wanted || wanted === '未知') continue;
    compared += 1;
    const actual = normalize(target[field]);
    if (actual === wanted || actual.includes(wanted) || wanted.includes(actual)) score += weight;
