async function loadPortraitCatalog(catalogUrl, {fetchImpl = globalThis.fetch, signal} = {}) {
  if (!catalogUrl) throw new Error('portrait catalogUrl 未配置');
  if (typeof fetchImpl !== 'function') throw new Error('当前环境缺少 fetch');
  const response = await fetchImpl(catalogUrl, {cache: 'no-cache', signal});
  if (!response.ok) throw new Error(`portrait catalog 加载失败: HTTP ${response.status}`);
  const catalog = await response.json();
  if (catalog?.schemaVersion !== 1 || !Array.isArray(catalog.groups) || !catalog.assets) {
    throw new Error('portrait catalog 结构不兼容');
  }
  return catalog;
}

function resolveNpcPortrait({npc, rollNatural, catalog, assignedGroupIds = []}) {
  if (!npc || !catalog) return null;
  if (npc.portraitGroupId && npc.portraitAssetKey) {
    return {
      portraitGroupId: npc.portraitGroupId,
      portraitAssetKey: npc.portraitAssetKey,
      portraitCatalogVersion: npc.portraitCatalogVersion ?? catalog.catalogVersion
    };
  }
  const blocked = new Set(assignedGroupIds.filter(Boolean));
  const candidates = catalog.groups
    .filter(group => group.adultOnly === true && !blocked.has(group.id))
    .map(group => ({group, ...scoreGroup(npc.appearanceProfile, group)}))
    .filter(candidate => candidate.compared > 0 && candidate.score > 0)
    .sort((left, right) => right.score - left.score || left.group.id.localeCompare(right.group.id));
  if (!candidates.length) return null;
  const topScore = candidates[0].score;
  const tied = candidates.filter(candidate => candidate.score === topScore);
  const rollSeed = Number.isInteger(rollNatural) && rollNatural >= 1 && rollNatural <= 20 ? rollNatural : null;
  const stableSource = String(npc.id || npc.name || JSON.stringify(npc.appearanceProfile || {}));
  let stableSeed = 2166136261;
  for (let index = 0; index < stableSource.length; index += 1) {
    stableSeed ^= stableSource.charCodeAt(index);
    stableSeed = Math.imul(stableSeed, 16777619) >>> 0;
  }
  const tieSeed = rollSeed ?? Math.max(1, stableSeed);
  const selected = tied[(tieSeed - 1) % tied.length].group;
  if (!selected.defaultPortraitAssetKey || !catalog.assets[selected.defaultPortraitAssetKey]) return null;
  return {
    portraitGroupId: selected.id,
    portraitAssetKey: selected.defaultPortraitAssetKey,
    portraitCatalogVersion: catalog.catalogVersion
  };
}

function resolvePortraitUrl(catalogUrl, assetKey, catalog) {
  const asset = catalog?.assets?.[assetKey];
  if (!asset?.path) return null;
  return new URL(asset.path, catalogUrl).href;
}

