    const copy = document.querySelector('.story-copy');
    if (copy) {
      copy.replaceChildren();
      const paragraphs = latestNarrative();
      const fallback = ['等待真实助手正文……'];
      [...(paragraphs.length ? paragraphs : fallback)].forEach((paragraph, index) => {
        const p = document.createElement('p');
        p.textContent = paragraph;
        if (!paragraphs.length && index > 0) p.className = 'meta-line';
        copy.append(p);
