        body.textContent = '玩家可以自由观察、移动或描述行动。';
      }
      alert.append(strong, body);
    }

    const actionRow = document.querySelector('.deflag-row');
    if (actionRow) {
      actionRow.replaceChildren();
      const messageChoices = choicesFromMessage(latestAssistantRaw());
      const choices = messageChoices.map((label, index) => ({id: `MESSAGE-${index + 1}`, label, kind: '本轮选项', reason: '', risk: ''}));
      if (!choices.length) {
        const empty = document.createElement('div');
        empty.className = 'projection-empty';
        empty.textContent = '当前没有系统建议行动，可直接在下方输入。';
        actionRow.append(empty);
