      choices.forEach((choice, index) => {
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'pixel-button option-card';
        button.dataset.actionChoice = choice.id;
        button.innerHTML = `<span class="option-number">${String(index + 1).padStart(2, '0')}</span><span class="option-title"></span><span class="option-risk"></span><span class="option-desc"></span>`;
        button.querySelector('.option-title').textContent = choice.label;
        button.querySelector('.option-risk').textContent = choice.risk || choice.kind || '可选';
        button.querySelector('.option-desc').textContent = choice.reason || '由玩家决定是否采用。';
        button.addEventListener('click', () => {
          selectedAction = choice.label;
          actionRow.querySelectorAll('button').forEach(item => item.classList.toggle('is-selected', item === button));
          writeActionInput(choice.label);
          notify(`已填入酒馆底部输入栏：${choice.label}。请用酒馆原生发送。`);
        });
        actionRow.append(button);
      });
      const reroll = document.createElement('button');
      reroll.type = 'button';
      reroll.className = 'pixel-button option-card option-card--reroll';
      reroll.dataset.rerollStory = 'true';
      reroll.disabled = rerolling;
