  async function cycleNpcPortrait(npc, control) {
    if (!npc?.id || !envelope?.stat_data?.npcs?.[npc.id]) return notify('当前人物还不能保存立绘。');
    let variants = npcPortraitVariants(npc);
    if (!variants.length) {
      try {
        await globalThis.MangaWorldPortraitAssets?.load?.();
        variants = npcPortraitVariants(npc);
      } catch {}
    }
    if (variants.length <= 1) return notify('这个人物目前只有一张可用立绘。');
    const currentIndex = Math.max(0, variants.findIndex(item => item.assetKey === npc.portraitAssetKey));
    const nextVariant = variants[(currentIndex + 1) % variants.length];
    if (!nextVariant?.assetKey) return notify('没有找到下一张立绘。');
    if (control) control.disabled = true;
    document.documentElement.dataset.portraitSaveState = 'saving';
    const previous = clone(envelope);
    let replaced = false;
    try {
      const next = clone(envelope);
      next.stat_data.npcs[npc.id].portraitAssetKey = nextVariant.assetKey;
      await replaceEnvelope(next, {render: false});
      replaced = true;
      if (!await saveChatNow()) throw new Error('当前酒馆没有可用的聊天保存入口');
      document.documentElement.dataset.portraitSaveState = 'saved';
      renderAll();
      const Mvu = runtime?.runtimeWindow?.Mvu;
      const eventEmit = runtime?.runtimeWindow?.eventEmit;
      if (typeof eventEmit === 'function' && Mvu?.events?.VARIABLE_UPDATE_ENDED) {
        try {
          await eventEmit(Mvu.events.VARIABLE_UPDATE_ENDED, next, previous);
        } catch (error) {
          console.error('[漫画世界模拟器] 立绘已保存，但变量刷新事件发送失败', error);
        }
      }
      notify(`已切换并保存 ${npc.name || npc.id} 的立绘（${(currentIndex + 1) % variants.length + 1}/${variants.length}）。`);
    } catch (error) {
      if (replaced) {
        try {
          await replaceEnvelope(previous, {render: false});
          await saveChatNow();
        } catch (rollbackError) {
          console.error('[漫画世界模拟器] 立绘保存失败后的变量回退也失败', rollbackError);
        }
      }
      envelope = previous;
      state = previous.stat_data;
      document.documentElement.dataset.portraitSaveState = 'error';
      renderAll();
      if (control) control.disabled = false;
      notify(error?.message || '立绘切换保存失败。');
    }
  }

