  function candidateFromRoll(natural, total, degree, rollId) {
    const namesA = ['许', '陆', '顾', '江', '周', '程', '沈', '贺', '林', '季', '温', '谢'];
    const namesB = ['屿', '川', '澈', '言', '衡', '远', '舟', '闻', '安', '野', '宁', '序'];
    const occupations = ['编辑', '程序员', '设计师', '医生', '教师', '摄影师', '咖啡师', '律师助理', '健身教练', '研究生', '产品经理', '书店店员'];
    const traits = ['慢热', '坦率', '细心', '幽默', '边界清楚', '容易紧张', '观察敏锐', '行动派', '嘴硬心软', '随和', '认真', '好奇心强'];
    const hairStyles = ['短碎发', '微卷短发', '侧分短发', '清爽寸发', '自然垂发', '后梳短发'];
    const hairColors = ['黑色', '深棕色', '栗色', '灰棕色'];
    const eyeColors = ['深棕色', '黑色', '茶色', '灰褐色'];
    const orientations = ['未知', '喜欢女性', '喜欢女性', '双性恋', '尚未确认'];
    const attitudes = ['顺其自然', '重视边界与沟通', '暂时不考虑恋爱', '愿意从朋友开始', '对关系比较谨慎'];
    const seed = natural * 37 + total * 13 + Number(rollId.replace(/\D/g, ''));
    const pick = (pool, offset) => pool[Math.abs(seed + offset * 17) % pool.length];
    const attribute = offset => Math.max(1, Math.min(20, 7 + ((seed + offset * 11) % 9) + (degree === 'critical_success' ? 2 : degree === 'critical_failure' ? -1 : 0)));
    const visualAge = natural % 3 === 0 ? '少年感' : '青年感';
    const hairStyle = pick(hairStyles, 4); const hairColor = pick(hairColors, 5); const eyeColor = pick(eyeColors, 6);
    return {
      name: `${pick(namesA, 0)}${pick(namesB, 1)}`,
      gender: '男', ageBand: '成年', identityLabel: `当前地点的${pick(occupations, 2)}`, occupation: pick(occupations, 2),
      traits: [pick(traits, 3), pick(traits, 7), degree === 'critical_failure' ? '初次见面有点手忙脚乱' : degree === 'critical_success' ? '初次见面格外自然' : '会先观察再行动'],
      appearanceText: `${visualAge}，${hairColor}${hairStyle}，${eyeColor}瞳。`,
      appearanceProfile: {visualAge, hairStyle, hairColor, eyeColor, featureTags: [visualAge, hairStyle, hairColor, eyeColor], adultConfirmed: true},
      orientationKnown: '未知',
      attributes: {charm: attribute(1), empathy: attribute(2), composure: attribute(3), initiative: attribute(4), flagSense: attribute(5)},
      romanceProfile: {orientation: pick(orientations, 8), relationshipAttitude: pick(attitudes, 9), currentRomanceGoal: '由后续真实事件决定'},
      goals: ['完成当前生活目标', '在不违背自身边界的前提下认识新的人'], knowledge: [], status: 'offscreen',
      firstSeenAt: '', lastSeenAt: '', currentLocationId: state.world?.locationId || '', portraitGroupId: null, portraitAssetKey: null, portraitCatalogVersion: null,
      generatedByRollId: rollId, archiveReason: '',
    };
  }

  function renderRollPanel() {
    const rolls = values(state.rolls).filter(roll => roll.triggerType === 'npc_generation').sort((a, b) => (a.rolledAtTurn ?? 0) - (b.rolledAtTurn ?? 0));
    const latest = rolls.at(-1);
    const candidate = pendingCandidate ?? latest?.candidateSnapshot ?? null;
    pendingCandidate = candidate && latest && !(latest.appliedNpcIds?.length) ? {...candidate, rollId: latest.id} : null;
    text('[data-dice-face]', latest?.natural ?? '?');
