        const outcome = document.createElement('span'); outcome.textContent = pendingCandidate ? `候选：${pendingCandidate.name} · ${pendingCandidate.occupation} · ${pendingCandidate.appearanceText}` : latest.appliedNpcIds?.length ? `已登记：${latest.appliedNpcIds.join('、')}` : latest.notes;
