  async function rollCandidate() {
    if (!envelope?.stat_data) return notify('MVU 尚未就绪，暂时不能投骰。');
    const next = clone(envelope); const data = next.stat_data;
    const natural = globalThis.crypto?.getRandomValues ? (globalThis.crypto.getRandomValues(new Uint32Array(1))[0] % 20) + 1 : Math.floor(Math.random() * 20) + 1;
    const nextId = data.meta.nextIds.roll; const rollId = padId('ROLL', nextId);
    const location = data.locations?.[data.world?.locationId];
    const modifiers = [{id: `${rollId}-LOC`, source: `${location?.name || '当前地点'} Flag密度`, value: densityModifier[location?.flagDensity] ?? 0, reason: '影响新人物在当前地点出现时的自然程度', expiresAtTurn: data.meta.turnNo}];
    for (const effect of values(data.correction?.activeEffects)) {
      if (typeof effect.value !== 'number' || (effect.expiresAtTurn != null && effect.expiresAtTurn < data.meta.turnNo)) continue;
      modifiers.push({id: effect.id || `${rollId}-FX-${modifiers.length}`, source: effect.source || '有效世界效果', value: effect.value, reason: effect.reason || '当前有效修正', expiresAtTurn: effect.expiresAtTurn ?? null});
    }
    const total = natural + modifiers.reduce((sum, item) => sum + item.value, 0); const difficulty = 10;
    const degree = natural === 20 ? 'critical_success' : natural === 1 ? 'critical_failure' : total >= difficulty ? 'success' : 'failure';
    const candidate = candidateFromRoll(natural, total, degree, rollId);
    data.rolls[rollId] = {id: rollId, triggerType: 'npc_generation', triggerRef: data.world?.sceneId || '', actorId: 'PLAYER', goal: '生成与当前地点合理相遇的成年女性 NPC 候选', stakes: '只影响候选的相遇顺利度与性格侧重；不改变玩家取向，不自动建立关系', rolledAtTurn: data.meta.turnNo, dice: '1d20', natural, modifiers, total, difficulty, degree, success: ['success', 'critical_success'].includes(degree), resultType: 'npc_candidate_preview', appliedNpcIds: [], appliedFlagIds: [], notes: `${degreeLabel[degree]}：已生成候选预览，等待玩家确认。`, candidateSnapshot: candidate};
    data.meta.nextIds.roll += 1; pendingCandidate = {...candidate, rollId};
    try { await replaceEnvelope(next); notify(`d20 投出 ${natural}：${degreeLabel[degree]}。候选尚未入池。`); } catch (error) { notify(error.message || '投骰记录写入失败。'); }
  }

  async function confirmCandidate() {
    if (!pendingCandidate?.rollId || !envelope?.stat_data) return;
    const next = clone(envelope); const data = next.stat_data; const roll = data.rolls?.[pendingCandidate.rollId];
    if (!roll || roll.appliedNpcIds?.length) return notify('这个候选已经处理过了。');
    const npcId = padId('NPC', data.meta.nextIds.npc);
    const npc = clone(pendingCandidate); delete npc.rollId;
    data.npcs[npcId] = {id: npcId, ...npc};
    roll.appliedNpcIds = [npcId]; roll.resultType = 'npc_registered'; roll.notes = `${degreeLabel[roll.degree]}：玩家确认候选 ${npc.name} 加入人物池，尚待正文正式登场。`;
    data.meta.nextIds.npc += 1; pendingCandidate = null; selectedNpcId = npcId;
    try {
      await replaceEnvelope(next);
      try { await reconcilePortraitBindings(); } catch (error) { console.error('[漫画世界模拟器] NPC 入池后的立绘匹配失败', error); }
      notify(`${npc.name} 已加入本局人物池；不会自动成为女主或恋爱对象。`);
    } catch (error) { notify(error.message || '候选写入失败。'); }
  }

