  function bindMiniWindows() {
    ensureMiniWindowDialogStyle();
    const miniWindows = [...document.querySelectorAll('[data-mini-window]')];
    const dialogMedia = matchMedia('(max-width: 560px)');
    const backdrop = document.createElement('button');
    backdrop.type = 'button';
    backdrop.className = 'mini-window-dialog-backdrop';
    backdrop.setAttribute('aria-label', '关闭辅助窗口');
    (document.querySelector('.desktop') || document.body).append(backdrop);
    let openPanel = null;
    let opener = null;

    const closeDialog = (restoreFocus = true) => {
      if (!openPanel) return;
      openPanel.classList.remove('is-dialog-open');
      openPanel.classList.add('is-collapsed');
      openPanel.removeAttribute('role');
      openPanel.removeAttribute('aria-modal');
      document.documentElement.removeAttribute('data-mini-window-dialog');
      const previousOpener = opener;
      openPanel = null;
      opener = null;
      if (restoreFocus) previousOpener?.focus();
    };

    const openDialog = (panel, title) => {
      closeDialog(false);
      miniWindows.forEach(item => {
        item.classList.add('is-collapsed');
        item.classList.remove('is-dialog-open');
      });
      openPanel = panel;
      opener = title;
      panel.classList.remove('is-collapsed');
      panel.classList.add('is-dialog-open');
      panel.setAttribute('role', 'dialog');
      panel.setAttribute('aria-modal', 'true');
      document.documentElement.dataset.miniWindowDialog = 'open';
      setTimeout(() => panel.querySelector('.mini-window__close')?.focus(), 0);
    };

    miniWindows.forEach((panel, index) => {
      panel.dataset.collapsible = 'true';
      const title = panel.querySelector('.mini-window__title');
      if (!title) return;
      const titleId = `manga-mini-window-title-${index + 1}`;
      title.id = title.id || titleId;
      title.tabIndex = 0;
      title.setAttribute('role', 'button');
      panel.setAttribute('aria-labelledby', title.id);
      const close = document.createElement('button');
      close.type = 'button';
      close.className = 'mini-window__close';
      close.setAttribute('aria-label', '关闭窗口');
      close.textContent = '×';
      title.append(close);

      const toggle = () => {
        if (dialogMedia.matches) {
          if (panel === openPanel) closeDialog();
          else openDialog(panel, title);
          return;
        }
        const opening = panel.classList.contains('is-collapsed');
        if (opening && matchMedia('(max-width: 920px)').matches) miniWindows.forEach(item => item.classList.add('is-collapsed'));
        panel.classList.toggle('is-collapsed', !opening);
      };
      title.addEventListener('click', toggle);
      title.addEventListener('keydown', event => {
        if (event.key === 'Enter' || event.key === ' ') {
          event.preventDefault();
          toggle();
        }
      });
      close.addEventListener('click', event => {
        event.stopPropagation();
        closeDialog();
      });
    });

    backdrop.addEventListener('click', () => closeDialog());
    const onKeydown = event => {
      if (event.key === 'Escape' && openPanel) {
        event.preventDefault();
        closeDialog();
      }
    };
    const onDialogMediaChange = () => {
      if (!dialogMedia.matches) closeDialog(false);
    };
    document.addEventListener('keydown', onKeydown);
    dialogMedia.addEventListener?.('change', onDialogMediaChange);
    disposers.push(() => {
      document.removeEventListener('keydown', onKeydown);
      dialogMedia.removeEventListener?.('change', onDialogMediaChange);
      backdrop.remove();
    });

    if (matchMedia('(max-width: 920px)').matches) {
      miniWindows.forEach(panel => panel.classList.add('is-collapsed'));
    }
  }

  function renderAll() {
    if (!state) return;
    renderMain();
    renderLocations();
    renderProfiles();
    renderCouples();
    renderTheaters();
    renderRollPanel();
    document.documentElement.dataset.mvuProjection = 'ready';
    return enableSameFloorPresentation();
  }

  function renderWaiting() {
    document.documentElement.dataset.mvuProjection = 'waiting';
    const cpBody = document.querySelector('.cp-list__body'); if (cpBody) cpBody.innerHTML = '<div class="projection-empty">正在读取当前存档的 CP 记录…</div>';
    const profileBody = document.querySelector('.file-list__body'); if (profileBody) profileBody.innerHTML = '<div class="projection-empty">正在读取当前存档的 NPC 注册表…</div>';
    const theaterBody = document.querySelector('.theater-menu__body'); if (theaterBody) theaterBody.innerHTML = '<div class="projection-empty">正在读取当前存档的小剧场…</div>';
  }

  function queueRefresh() {
    if (writing || refreshQueued) return;
    refreshQueued = true;
    setTimeout(async () => {
      refreshQueued = false;
      try {
        const next = await readEnvelope();
        if (next?.stat_data) { envelope = next; state = next.stat_data; }
        renderAll();
      } catch (error) { console.error('[漫画世界模拟器] 五页投影刷新失败', error); }
    }, 0);
  }

  async function start() {
    bindCoreButtons(); bindMiniWindows(); renderWaiting();
    runtime = await waitForRuntime();
    const Mvu = runtime?.runtimeWindow?.Mvu;
    if (!Mvu?.getMvuData) {
      state = clone(globalThis.__MANGA_WORLD_INITIAL_STATE__ || {world:{},actions:{choices:[]}});
      renderAll();
    } else {
      let current = await readEnvelope();
      if ((!current?.stat_data || !Object.keys(current.stat_data).length) && globalThis.__MANGA_WORLD_INITIAL_STATE__) {
        const initialized = clone(current && typeof current === 'object' ? current : {});
        initialized.stat_data = clone(globalThis.__MANGA_WORLD_INITIAL_STATE__);
        await replaceEnvelope(initialized);
        current = await readEnvelope();
        if (!current?.stat_data || !Object.keys(current.stat_data).length) throw new Error('默认 MVU 写入后仍未读回');
      }
      if (!current?.stat_data) throw new Error('当前消息没有可读取的 stat_data，且卡内初始状态不可用');
      envelope = current; state = current.stat_data; renderAll();
    }
    const eventOn = runtime?.runtimeWindow?.eventOn;
    if (typeof eventOn === 'function') {
      const tavernEvents = runtime.runtimeWindow.tavern_events || {};
      for (const eventName of [Mvu?.events?.VARIABLE_INITIALIZED, Mvu?.events?.VARIABLE_UPDATE_ENDED, tavernEvents.MESSAGE_RECEIVED, tavernEvents.MESSAGE_UPDATED, tavernEvents.MESSAGE_SWIPED].filter(Boolean)) {
        const handle = eventOn(eventName, queueRefresh);
        if (handle?.stop) disposers.push(() => handle.stop());
      }
    }
    const onPortraitAssetsReady = () => renderProfiles();
    globalThis.addEventListener?.('manga-world-portrait-assets-ready', onPortraitAssetsReady);
    disposers.push(() => globalThis.removeEventListener?.('manga-world-portrait-assets-ready', onPortraitAssetsReady));
    void globalThis.MangaWorldPortraitAssets?.load?.().then(() => renderProfiles()).catch(() => {});
    window.addEventListener('pagehide', () => { disableSameFloorPresentation(); while (disposers.length) { try { disposers.pop()?.(); } catch {} } }, {once: true});
    console.info(`[漫画世界模拟器] MVU 五页投影已就绪 v${VERSION}`);
  }

  void start().catch(error => {
    disableSameFloorPresentation();
    document.documentElement.dataset.mvuProjection = 'error';
    console.error('[漫画世界模拟器] MVU 五页投影启动失败', error);
    notify('MVU 投影启动失败，请检查酒馆助手与变量初始化。');
  });
})();

