export async function registerMangaWorldSchema() {
  if (typeof globalThis.eventOn !== 'function' || typeof globalThis.registerVariableSchema !== 'function') {
    throw new Error('酒馆助手能力未就绪：需要 eventOn 与 registerVariableSchema。');
  }
  const Schema = createMangaWorldSchema(globalThis.z);
  let helper;
  try {
    helper = await import(PRIMARY_HELPER);
  } catch (primaryError) {
    try {
      helper = await import(FALLBACK_HELPER);
    } catch (fallbackError) {
      throw new AggregateError([primaryError, fallbackError], 'MVU Zod 注册 helper 主备地址均加载失败。');
    }
  }
  if (typeof helper.registerMvuSchema !== 'function') throw new Error('远程 helper 未导出 registerMvuSchema。');
  helper.registerMvuSchema(Schema);
  return Schema;
}

function startMangaWorldSchemaRegistration() {
  const register = () => Promise.resolve(registerMangaWorldSchema());
  if (typeof globalThis.$ !== 'function') return register();
  return new Promise((resolve, reject) => {
    globalThis.$(() => { void register().then(resolve, reject); });
  });
}

