当前已登记 NPC：${known}
当前下一个 NPC：${next.id}（/meta/nextIds/npc 当前值 ${next.number}）
当前地点 ID：${locationId}

若本轮需要登记当前下一个 NPC，<JSONPatch> 内的数组至少包含下面两项，并把示例事实替换为正文已经成立的事实；未知值写“未知”或空数组，字段不得省略：
{"op":"add","path":"/npcs/${next.id}","value":{"id":"${next.id}","name":"稳定姓名或临时称谓","gender":"男","ageBand":"成年","identityLabel":"当前身份","occupation":"未知","traits":["可核验特征"],"appearanceText":"青年女性，黑色短发，深色眼睛","appearanceProfile":{"visualAge":"青年感","hairStyle":"黑色短发","hairColor":"黑色","eyeColor":"深色","featureTags":[],"adultConfirmed":true},"orientationKnown":"未知","attributes":{"charm":10,"empathy":10,"composure":10,"initiative":10,"flagSense":10},"romanceProfile":{"orientation":"未知","relationshipAttitude":"顺其自然","currentRomanceGoal":"无明确目标"},"goals":[],"knowledge":[],"status":"active","firstSeenAt":"当前回合","lastSeenAt":"当前回合","currentLocationId":"${locationId}","portraitGroupId":null,"portraitAssetKey":null,"portraitCatalogVersion":null,"generatedByRollId":null,"archiveReason":""}}
{"op":"replace","path":"/meta/nextIds/npc","value":${next.number + 1}}

结束回复前逐字自检：必须同时存在 <content>…</content>、<UpdateVariable>…<JSONPatch>[…]</JSONPatch>…</UpdateVariable> 和行动选项；缺任何一个就先修正再结束。
只能使用复数根 /npcs/；ID 必须带连字符；appearanceProfile.visualAge 只能是“少年感”“青年感”或“未知”；属性只能是 charm/empathy/composure/initiative/flagSense；恋爱字段只能是 romanceProfile。禁止 /npc/、NPC0001、visualAge“青年”、str/dex/con/int/wis/cha、romance。立绘三个字段先写 null，后续由卡内立绘绑定器自动匹配。`;
  }

  function injectContract() {
    try {
      if (activeInjection?.uninject) activeInjection.uninject();
      else if (typeof globalThis.uninjectPrompts === 'function') globalThis.uninjectPrompts([INJECTION_ID]);
      activeInjection = null;
