(() => {
  'use strict';

  function normalize(value) {
    return String(value || '')
      .replace(/<[^>]*>/g, ' ')
      .replace(/^\s*(?:[-*•]|\d+[.)、])\s*/, '')
      .replace(/\s+/g, ' ')
      .trim();
  }

  function pipeChoices(value) {
    const choices = [];
    for (const match of String(value || '').matchAll(/\[Options?\|([\s\S]*?)\]/gi)) choices.push(...match[1].split('|'));
    return choices;
  }

  function appendCandidates(candidates, value) {
    const piped = pipeChoices(value);
    candidates.push(...(piped.length ? piped : [value]));
  }

  function parse(raw) {
    const source = String(raw || '');
    const candidates = [];
    for (const match of source.matchAll(/<(?:option|choice|选项)\b[^>]*>([\s\S]*?)<\/(?:option|choice|选项)>/gi)) appendCandidates(candidates, match[1]);
    for (const match of source.matchAll(/<(?:choices|options|options_panel|选项)\b[^>]*>([\s\S]*?)<\/(?:choices|options|options_panel|选项)>/gi)) {
      const nested = [...match[1].matchAll(/<(?:option|choice|选项)\b[^>]*>([\s\S]*?)<\/(?:option|choice|选项)>/gi)].map(item => item[1]);
      if (nested.length) nested.forEach(value => appendCandidates(candidates, value));
      else {
        const piped = pipeChoices(match[1]);
        candidates.push(...(piped.length ? piped : match[1].split(/\r?\n/)));
      }
    }
    candidates.push(...pipeChoices(source));
    return [...new Set(candidates.map(normalize).filter(Boolean))].slice(0, 6);
  }

  globalThis.MangaWorldChoiceParser = Object.freeze({parse});
})();

