      await Mvu.replaceMvuData(next, MESSAGE_SCOPE);
      if (typeof globalThis.eventEmit === 'function' && Mvu.events?.VARIABLE_UPDATE_ENDED) {
        await globalThis.eventEmit(Mvu.events.VARIABLE_UPDATE_ENDED, next, current);
      }
      const host = globalThis.SillyTavern;
      const context = host?.getContext?.();
      if (typeof host?.saveChat === 'function') await host.saveChat();
      else if (typeof context?.saveChat === 'function') await context.saveChat();
    } finally {
      writing = false;
    }
    return {changed: true, npcIds: changes.map(change => change.npcId)};
  }

  async function start() {
    if (!catalogUrl) return {started: false, reason: 'catalog-url-missing'};
    const Mvu = await waitForGlobal('Mvu');
    if (!Mvu?.events || typeof globalThis.eventOn !== 'function') return {started: false, reason: 'mvu-events-unavailable'};
    for (const eventName of [Mvu.events.VARIABLE_INITIALIZED, Mvu.events.VARIABLE_UPDATE_ENDED].filter(Boolean)) {
      const delayMs = eventName === Mvu.events.VARIABLE_UPDATE_ENDED ? 120 : 0;
      const handle = globalThis.eventOn(eventName, () => scheduleReconcile(delayMs));
      if (handle?.stop) disposers.push(() => handle.stop());
    }
    if (globalThis.tavern_events?.MESSAGE_RECEIVED) {
      const handle = globalThis.eventOn(globalThis.tavern_events.MESSAGE_RECEIVED, () => scheduleReconcile(800));
      if (handle?.stop) disposers.push(() => handle.stop());
    }
    await reconcile();
    return {started: true};
  }

  function destroy() {
    destroyed = true;
    while (disposers.length) {
      try { disposers.pop()?.(); } catch {}
    }
    for (const timer of timers) clearTimeout(timer);
    timers.clear();
  }

  return {start, reconcile, destroy};
}

async function startConfiguredPortraitBinder() {
  globalThis.MangaWorldPortraitBinder?.destroy?.();
  const catalogUrl = globalThis.__MANGA_WORLD_PORTRAIT_CATALOG_URL__ ?? null;
  const binder = createPortraitBinder({catalogUrl});
  globalThis.MangaWorldPortraitBinder = binder;
  return binder.start();
}

void startConfiguredPortraitBinder().catch(error => console.error('[漫画世界模拟器] 立绘目录启动失败', error));
